            public long modulus() {
                return 998_244_353L;
            }
        }

        abstract static class Modulus<M extends Modulus<M>> {
            final IntStack factorials = new IntStack();
            final IntStack invFactorials = new IntStack();

            public abstract long modulus();

            public Modulus() {
                factorials.push(1);
                invFactorials.push(1);
            }

            public long fact(int n) {
                while (factorials.size() <= n) {
                    factorials.push((int) mult(factorials.get(factorials.size() - 1), factorials.size()));
                }
                return factorials.get(n);
            }

            public long fInv(int n) {
                int lastIdx = invFactorials.size() - 1;
                if (lastIdx < n) {
                    long[] invs = new long[n - lastIdx];
                    invs[0] = inv(fact(n));
                    for (int i = 1; i < invs.length; i++) {
                        invs[i] = mult(invs[i - 1], n - i + 1);
                    }
                    for (int i = invs.length - 1; i >= 0; i--) {
                        invFactorials.push((int) invs[i]);
                    }
                }
                return invFactorials.get(n);
            }

            public long paritySign(long k) {
                return (k & 1) == 0 ? 1 : modulus() - 1;
            }

            public long ncr(int n, int r) {
                if (n < 0 || r < 0 || n < r) return 0;
                return mult(fact(n), mult(fInv(r), fInv(n - r)));
            }

            public long smallInv(int n) {
                return mult(fInv(n), fact(n - 1));
            }

            public long add(long a, long b) {
                long sum = a + b;
                return sum >= modulus() ? sum - modulus() : sum;
            }

            public long mult(long a, long b) {
                return (a * b) % modulus();
            }
        }
    }

    static class IntStack {
        int[] data;
        int size;

        public IntStack() {
            this(8);
        }

        public IntStack(int capacity) {
            data = new int[capacity];
            size = 0;
        }

        public void push(int val) {
            if (size >= data.length) {
                data = resize(data);
            }
            data[size++] = val;
        }

        public int get(int index) {
            if (index >= size) throw new AssertionError();
            return data[index];
        }

        public int size() {
            return size;
        }

        private static int[] resize(int[] array) {
            int[] newArr = new int[array.length * 2];
            System.arraycopy(array, 0, newArr, 0, array.length);
            return newArr;
        }
    }
