import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353
            self.factorials = IntStack()
            self.invFactorials = IntStack()
            self.factorials.push(1)
            self.invFactorials.push(1)

        def modulus(self):
            return self.modulus_value

        def fact(self, n):
            while self.factorials.size() <= n:
                self.factorials.push(self.mult(self.factorials.get(self.factorials.size() - 1), self.factorials.size()))
            return self.factorials.get(n)

        def fInv(self, n):
            lastIdx = self.invFactorials.size() - 1
            if lastIdx < n:
                invs = [0] * (n - lastIdx)
                invs[0] = self.mult(self.fact(n), self.modinv(self.fact(n)))
                for i in range(1, len(invs)):
                    invs[i] = self.mult(invs[i - 1], n - i + 1)
                for i in reversed(range(len(invs))):
                    self.invFactorials.push(invs[i])
            return self.invFactorials.get(n)

        def paritySign(self, k):
            return 1 if (k & 1) == 0 else self.modulus() - 1

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return self.mult(self.fact(n), self.mult(self.fInv(r), self.fInv(n - r)))

        def smallInv(self, n):
            return self.mult(self.fInv(n), self.fact(n - 1))

        def add(self, a, b):
            sum_ab = a + b
            return sum_ab - self.modulus() if sum_ab >= self.modulus() else sum_ab

        def mult(self, a, b):
            return (a * b) % self.modulus()

        def modinv(self, a):
            # Extended Euclidean Algorithm for modular inverse
            m = self.modulus()
            g, x, y = self.extended_gcd(a, m)
            if g != 1:
                return 1  # Inverse doesn't exist, but for prime modulus, it should
            else:
                return x % m

        def extended_gcd(self, a, b):
            if b == 0:
                return (a, 1, 0)
            else:
                g, y, x = self.extended_gcd(b, a % b)
                return (g, x, y - (a // b) * x)

class IntStack:
    def __init__(self, capacity=8):
        self.data = [0] * capacity
        self.size = 0

    def push(self, val):
        if self.size >= len(self.data):
            self.data = self.resize(self.data)
        self.data[self.size] = val
        self.size += 1

    def get(self, index):
        if index >= self.size:
            raise AssertionError()
        return self.data[index]

    def size(self):
        return self.size

    @staticmethod
    def resize(array):
        newArr = [0] * (len(array) * 2)
        newArr[:len(array)] = array
        return newArr

